        ouc = uc = json_skip_space(*ucp, ue);
        if (uc == ue)
                goto out;

        // Avoid recursion
        if (lvl > 500) {
                DPRINTF("Too many levels", uc, *ucp);
                return 0;
        }
#if JSON_COUNT
